{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Scandoside methyl ester, an iridoid glycoside, was detected in rat brain microdialysates and tissue homogenates, directly demonstrating that iridoid-type natural products can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Deacetyl asperulosidic acid methyl ester, another iridoid glycoside, crossed the BBB in rats, supporting CNS access for the iridoid scaffold shared by the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Picroside-I, an iridoid glycoside, rapidly penetrated the BBB and was detected in rat brain tissue, providing direct evidence for iridoid CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Dehydroascorbic acid is actively transported across the BBB by GLUT1, showing that small polar polyhydroxylated molecules can achieve transporter-mediated brain uptake despite poor passive permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Hydroxysafflor yellow A reached 1026 ng/g in rat brain in a normal tissue distribution study, demonstrating that even very polar glycosides can achieve meaningful brain concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "2-Deoxyglucose crosses the BBB and appears in CSF, further supporting carrier-mediated brain entry for small polar sugar-like scaffolds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. High-transfer direct evidence shows that polar iridoid glycosides and small sugar-like molecules cross the BBB, often via transporters; the query's iridoid aglycone is consistent with meaningful CNS access despite low predicted passive permeability.",
  "evidence_gaps": [
    "No direct brain, plasma, or CSF measurement exists for the query molecule itself.",
    "Transporter substrate status (e.g., GLUT, nucleoside, OATP, P-gp) is not experimentally defined for the query.",
    "Most supporting evidence is qualitative or from glycosides; quantitative unbound brain exposure for the aglycone is lacking.",
    "Potential rapid metabolism or efflux of the epoxide-containing aglycone is not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

